import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.regex.Pattern;

// Tento fragment ukazuje opravený, bezpečný fragment kódu.
// Používá ověření a sanitizaci vstupu, aby se předešlo zranitelnostem.
public class SecureExample {
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine(); // Přečte vstup
            // Ověřte, zda vstup je platný (např. pouze alfanumеричесké znaky, bez speciálních znaků)
            // Použijte regex pro ověření formátu, aby se předešlo nebezpečným řetězcům
            Pattern safePattern = Pattern.compile("^[a-zA-Z0-9_]+$");
            if (safePattern.matcher(line).matches()) {
                // Vstup je bezpečný – můžeme jej použít bez rizika
                System.out.println("Bezpečný vstup přečten: " + line);
            } else {
                // Pokud vstup není platný, odmítně ho a zpracujte chybu (např. logujte, vraťte chybu)
                System.err.println("Záměrný nebezpečný vstup přijat – odmítnut.");
                // Tím se zabrání útoku, např. XSS, SQL injection atd.
            }
        }
    }
}

